const rows = $input.all().map(i => i.json);
const estado = (rows.find(r => r.clave === 'Estado_Campana') || {}).valor || 'Pausada';
const activa = estado.toString().trim().toLowerCase() === 'activa';
return [{ json: { estadoCampana: estado, activa } }];

function diffMin(fechaStr) {
  if (!fechaStr) return -1;
  const f = new Date(fechaStr.toString().replace(' ', 'T'));
  if (isNaN(f.getTime())) return -1;
  return (Date.now() - f.getTime()) / 60000;
}

const tandas = $('Leer Plantillas').all().map(i => i.json).sort((a, b) => Number(a.tanda) - Number(b.tanda));
// Plantillas_Mail esta vinculada a la tanda (no al lead): cada tanda define que .html usar.
const plantillasMail = $('Leer Plantillas_Mail').all().map(i => i.json);

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if ((j['desuscripto'] || '').toString().trim().toLowerCase() === 'si') continue;
  if (!j.email) continue;

  for (const t of tandas) {
    const n = Number(t.tanda);
    const envioN = (j['Envio' + n] || '').toString().trim();
    const emailEnvioN = (j['EmailEnvio' + n] || '').toString().trim();
    if (envioN !== 'Si') continue;      // el SMS de esta tanda no se mando (o fallo)
    if (emailEnvioN !== '') continue;   // el mail de esta tanda ya se envio

    const delayMin = Number(t['delay_mail_min'] || 30);
    if (diffMin(j['FechaEnvio' + n]) < delayMin) continue; // no paso la ventana de espera

    const plantillaMail = plantillasMail.find(p => Number(p.tanda) === n);
    if (!plantillaMail || !plantillaMail.archivo_template) continue; // tanda sin template de mail configurado -> no se envia

    out.push({
      json: {
        row_number: j.row_number,
        nombre: j.nombre || '',
        email: j.email,
        codigo: j.codigo,
        tanda: n,
        archivo_template: plantillaMail.archivo_template
      }
    });
    break; // 1 mail por corrida por lead; las tandas restantes se procesan en la proxima corrida
  }
}
return out;

const j = $json;
const n8nBase = $('Config').first().json.N8N_BASE_URL;
const unsubUrl = `${n8nBase}/webhook/mail-baja/${j.codigo}`;
const clickUrl = `${n8nBase}/webhook/mail-click/${j.codigo}-${j.tanda}`;

let html = j.text || j.data || '';
html = html.replace(/\[email\]/g, j.email);
// Reemplaza el href del link "quiero desuscribirme" (identificado por su id fijo en el template).
html = html.replace(/(href=")[^"]*("[^>]*id="unlayer-custom-tool-footer-unsubscribe-link")/, `$1${unsubUrl}$2`);
// Reemplaza el href del boton CTA principal (identificado por su clase fija en el template).
html = html.replace(/(href=")[^"]*("[^>]*class="v-button")/, `$1${clickUrl}$2`);

return { json: { row_number: j.row_number, tanda: j.tanda, email: j.email, html } };

const j = $('Armar Mail (placeholders + tracking)').item.json;
const n = j.tanda;
const out = { row_number: j.row_number };
out['EmailEnvio' + n] = new Date().toISOString().slice(0, 19).replace('T', ' ');
return [{ json: out }];
